<script setup lang="ts">
import {computed,inject,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {RouterLink} from 'vue-router';
import {adminSessionKey} from './adminSession';
import {paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions,userDirectoryDetailGetApiV1AdminUsersIdDirectoryDetail,accessAdminSecretGetApiV1AdminAccessKeysIdSecret,billingEntriesGetApiV1BillingWalletsKeyIdLedger,billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments,paymentAdminHistoryGetApiV1AdminPaymentsRecharges,billingListGetApiV1AdminBillingConsumptions} from './api';
import PromoterIcon from './PromoterIcon.vue';
import AmountAdjustment from './AmountAdjustment.vue';
import UserAccount from './UserAccount.vue';
import {formatAmount} from '../../shared/formatAmount';
import {ApiError,userRenamePatchApiV1AdminUsersIdNickname} from './api';
const props=defineProps<{userId:string}>(),emit=defineEmits<{changed:[]}>();
const session=inject(adminSessionKey),primary=computed(()=>session?.currentAdmin.value?.role==='ADMIN'&&session.currentAdmin.value.primary===true);
const canRename=computed(()=>['ADMIN','NORMAL_ADMIN'].includes(session?.currentAdmin.value?.role||''));
const editingName=ref(false),nameDraft=ref(''),nameSaving=ref(false),nameError=ref(''),nameSaved=ref(false);
const nameInput=ref<HTMLInputElement|null>(null),nameButton=ref<HTMLButtonElement|null>(null);
let nameVersion=0;
async function editName(){if(!canRename.value||nameSaving.value||!detail.value?.user)return;nameDraft.value=detail.value.user.nickname||'';nameError.value='';nameSaved.value=false;editingName.value=true;await nextTick();nameInput.value?.focus();nameInput.value?.select();}
async function cancelName(){if(nameSaving.value)return;editingName.value=false;nameError.value='';await nextTick();nameButton.value?.focus();}
async function saveName(){
 if(!canRename.value||nameSaving.value||!editingName.value||!detail.value?.user)return;
 const nickname=nameDraft.value.trim();
 if(!nickname||nameDraft.value.length>64||/[\u0000-\u001f\u007f-\u009f]/u.test(nameDraft.value)){nameError.value='请输入 1–64 个字符的用户名，不可包含控制字符。';nameInput.value?.focus();return;}
 if(nickname===detail.value.user.nickname){await cancelName();return;}
 const id=props.userId,request=++nameVersion,owner=session?.currentAdmin.value;
 nameSaving.value=true;nameError.value='';
 try{
  const {data}=await userRenamePatchApiV1AdminUsersIdNickname(id,{nickname});
  if(!alive||request!==nameVersion||id!==props.userId||owner!==session?.currentAdmin.value||!canRename.value)return;
  if(data.id!==id||!data.nickname)throw Error('Unexpected user');
  detail.value={...detail.value,user:{...detail.value.user,nickname:data.nickname}};
  editingName.value=false;nameSaved.value=true;emit('changed');await nextTick();nameButton.value?.focus();
 }catch(cause){
  if(alive&&request===nameVersion&&id===props.userId){nameError.value=cause instanceof ApiError&&cause.status===403?'当前账号无权修改用户名，请重新登录后重试。':cause instanceof ApiError&&cause.status===404?'该用户已不存在，请返回用户列表核对。':cause instanceof ApiError&&cause.status===400?'用户名不符合要求，请输入 1–64 个字符。':'保存未确认，输入已保留，请重试或刷新核对。';}
 }finally{if(alive&&request===nameVersion)nameSaving.value=false;}
}
watch([()=>props.userId,()=>session?.currentAdmin.value],()=>{nameVersion++;editingName.value=false;nameSaving.value=false;nameError.value='';nameSaved.value=false;});
watch(()=>props.userId,()=>{detail.value=null;void reload();});
const detail=ref<Awaited<ReturnType<typeof userDirectoryDetailGetApiV1AdminUsersIdDirectoryDetail>>['data']|null>(null),busy=ref(false),error=ref(''),recordError=ref(''),recordBusy=ref(false),copied=ref('');
const tab=ref('funds'),recordOffset=ref(0),recordTotal=ref(0),ledger=ref<Awaited<ReturnType<typeof billingEntriesGetApiV1BillingWalletsKeyIdLedger>>['data']>([]),audit=ref<Awaited<ReturnType<typeof billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments>>['data']>([]),recharges=ref<Awaited<ReturnType<typeof paymentAdminHistoryGetApiV1AdminPaymentsRecharges>>['data']>([]),consumptions=ref<NonNullable<Awaited<ReturnType<typeof billingListGetApiV1AdminBillingConsumptions>>['data']['items']>>([]);
const adjusting=ref(false),adjustmentBusy=ref(false),adjustmentError=ref(''),adjustmentOptions=ref<Awaited<ReturnType<typeof paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions>>['data']|null>(null);
const typeDialog=ref<HTMLDialogElement|null>(null),typeEditor=ref<InstanceType<typeof UserAccount>|null>(null),typeOpen=ref(false);
async function openType(){typeOpen.value=true;await nextTick();typeDialog.value?.showModal();}
function closeType(){if(typeEditor.value?.busy)return;typeDialog.value?.close();typeOpen.value=false;}
function typeSaved(){typeDialog.value?.close();typeOpen.value=false;emit('changed');}
let adjustmentVersion=0;
async function openAdjustment(){adjusting.value=true;adjustmentBusy.value=true;adjustmentError.value='';const request=++adjustmentVersion;try{const result=await paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions({userId:props.userId});if(!alive||request!==adjustmentVersion)return;if(result.data.userId!==props.userId)throw Error();adjustmentOptions.value=result.data;}catch{if(alive&&request===adjustmentVersion)adjustmentError.value='无法读取账户充值规则，请重试。';}finally{if(alive&&request===adjustmentVersion)adjustmentBusy.value=false;}}
function cancelAdjustment(){adjustmentVersion++;adjusting.value=false;adjustmentOptions.value=null;}
let version=0,recordVersion=0,alive=true;
const pointsPerYuan=ref<string|null>(null);
async function loadConversion(request:number){
 try{const {data}=await paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions({userId:props.userId});if(alive&&request===version&&data.userId===props.userId)pointsPerYuan.value=data.pointsPerYuan4??null;}catch{if(alive&&request===version)pointsPerYuan.value=null;}
}
const groupedPoints=(value:string|null|undefined)=>formatAmount(value).replace(/^(-?\d+)/,part=>part.replace(/\B(?=(\d{3})+(?!\d))/g,','));
const names:Record<string,string>={PERSONAL:'个人用户',ENTERPRISE:'企业用户',API:'API 用户',UNSET:'普通用户',RECHARGE:'充值',CONSUME:'消费',REFUND:'退款',ADMIN_ADJUST:'人工调整',ADJUSTMENT:'人工调整',SUCCEEDED:'成功',PARTIAL_SUCCESS:'部分成功',FAILED:'失败',RUNNING:'生成中',TIMED_OUT:'已超时',PAID:'待到账',REFUNDED:'已退款',CREATED:'待支付',PENDING:'待审核',REJECTED:'已驳回',APPROVED:'待到账',CLOSED:'已关闭',EXPIRED:'已过期'};
const tabs=[['funds','资金记录'],['recharges','充值记录'],['consumptions','消费记录'],['generations','生成记录'],['audit','账户日志']] as const;
const date=(value:string|null|undefined)=>value?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)).replaceAll('/','-'):'—';
const yuan=(value:string|null|undefined)=>value==null?'—':`${value.split('.')[0]!.replace(/\B(?=(\d{3})+(?!\d))/g,',')}.${(value.split('.')[1]||'').padEnd(2,'0').slice(0,2)}`;
async function reload(){const request=++version;busy.value=true;error.value='';pointsPerYuan.value=null;try{const result=await userDirectoryDetailGetApiV1AdminUsersIdDirectoryDetail(props.userId);if(!alive||request!==version)return;if(result.data.user?.id!==props.userId)throw Error();detail.value=result.data;void loadConversion(request);await loadRecords();}catch{if(alive&&request===version){detail.value=null;error.value='无法读取用户详情，请重试。';}}finally{if(alive&&request===version)busy.value=false;}}
async function loadRecords(){const request=++recordVersion;recordBusy.value=true;recordError.value='';ledger.value=[];audit.value=[];recharges.value=[];consumptions.value=[];recordTotal.value=0;const selectedTab=tab.value,key=detail.value?.user?.keyId;
 try{if(selectedTab==='funds'&&key){const result=await billingEntriesGetApiV1BillingWalletsKeyIdLedger(key,{limit:100});if(alive&&request===recordVersion)ledger.value=result.data;}
 else if(selectedTab==='audit'&&key){const result=await billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments(key);if(alive&&request===recordVersion)audit.value=result.data;}
 else if(selectedTab==='recharges'){const result=await paymentAdminHistoryGetApiV1AdminPaymentsRecharges({userId:props.userId});if(alive&&request===recordVersion)recharges.value=result.data;}
 else if(selectedTab==='consumptions'||selectedTab==='generations'){const result=await billingListGetApiV1AdminBillingConsumptions({userId:props.userId,to:new Date().toISOString(),offset:recordOffset.value,limit:10});if(alive&&request===recordVersion){consumptions.value=result.data.items||[];recordTotal.value=result.data.total;}}
 }catch{if(alive&&request===recordVersion)recordError.value='记录读取失败，请重试。';}finally{if(alive&&request===recordVersion)recordBusy.value=false;}}
function selectTab(value:string){tab.value=value;recordOffset.value=0;void loadRecords();}
async function tabKey(event:KeyboardEvent){const index=tabs.findIndex(([id])=>id===tab.value);const target=event.key==='ArrowRight'?(index+1)%tabs.length:event.key==='ArrowLeft'?(index+tabs.length-1)%tabs.length:event.key==='Home'?0:event.key==='End'?tabs.length-1:null;if(target===null)return;event.preventDefault();selectTab(tabs[target]![0]);await nextTick();document.getElementById(`user-record-tab-${tab.value}`)?.focus();}
async function copyPhone(){try{if(detail.value?.user?.phone){await navigator.clipboard.writeText(detail.value.user.phone);if(alive)copied.value='phone';}}catch{if(alive)error.value='复制失败，请重试。';}}
async function copyKey(){const id=detail.value?.user?.keyId;if(!primary.value||!id)return;try{const result=await accessAdminSecretGetApiV1AdminAccessKeysIdSecret(id);if(alive&&primary.value&&result.data.secret){await navigator.clipboard.writeText(result.data.secret);if(alive)copied.value='key';}}catch{if(alive)error.value='复制 Key 失败，请重试。';}}
onMounted(()=>void reload());onBeforeUnmount(()=>{alive=false;version++;recordVersion++;adjustmentVersion++;nameVersion++;});defineExpose({reload});
</script>
<template><div class="user-detail-content"><p v-if="error" role="alert">{{error}} <button @click="reload">重试</button></p><p v-if="busy&&!detail" role="status">正在读取用户详情…</p><template v-if="detail?.user"><section class="detail-profile"><span class="profile-avatar"><svg viewBox="0 0 64 64" fill="currentColor" stroke="#fff" stroke-opacity=".55" stroke-width="1.5" aria-hidden="true"><circle cx="32" cy="18" r="13"/><path d="M9 56v-3c0-12 9-19 23-19s23 7 23 19v3a3 3 0 0 1-3 3H12a3 3 0 0 1-3-3Z"/></svg></span><div><div class="profile-name-row"><h3>{{detail.user.nickname}} <span class="pill" :class="detail.user.enabled?'green':'red'">● {{detail.user.enabled?'正常':'停用'}}</span></h3><button v-if="canRename&&!editingName" ref="nameButton" type="button" class="profile-edit" :disabled="busy" @click="editName">修改用户名</button></div>
<form v-if="editingName" class="profile-name-form" aria-label="修改用户名" :aria-busy="nameSaving" @submit.prevent="saveName" @keydown.esc.stop.prevent="cancelName">
 <label for="detail-username">用户名</label><div class="profile-name-controls"><input id="detail-username" ref="nameInput" v-model="nameDraft" name="nickname" maxlength="64" required autocomplete="off" :disabled="nameSaving" :aria-invalid="!!nameError" :aria-describedby="nameError?'detail-username-error':undefined"/><button type="submit" class="primary-action" :disabled="nameSaving">{{nameSaving?'保存中…':'保存'}}</button><button type="button" :disabled="nameSaving" @click="cancelName">取消</button></div>
 <p v-if="nameError" id="detail-username-error" role="alert">{{nameError}}</p>
</form><p v-if="nameSaved" role="status">用户名已更新</p><p class="copy-cell">{{detail.user.phone?.replace(/^\+86/,'')}}<button class="icon-button" aria-label="复制手机号" @click="copyPhone"><span v-if="copied==='phone'">✓</span><PromoterIcon v-else name="copy"/></button></p><p class="profile-meta"><span>注册时间：{{date(detail.user.registeredAt)}}</span><span :title="detail.user.id||''">用户 ID：{{detail.user.id}}</span></p></div></section>
<p v-if="detail.user.remark" class="detail-user-remark">备注：{{detail.user.remark}}</p>
<section class="detail-identity"><button class="identity-type" :class="{'api-type':detail.user.accountType==='API'}" aria-haspopup="dialog" @click="openType"><PromoterIcon name="bank"/>{{names[detail.user.accountType||'UNSET']}}<span>⌄</span></button><div class="detail-key"><PromoterIcon name="lock"/><strong>{{detail.user.keyStatus==='NONE'?'Key 未生成':detail.user.keyStatus==='DISABLED'?'Key 已停用':'Key 已生成'}}</strong><span>{{detail.user.maskedKey||'—'}}</span><button v-if="primary&&detail.user.keyId" class="icon-button" aria-label="复制用户 Key" @click="copyKey"><span v-if="copied==='key'">✓</span><PromoterIcon v-else name="copy"/></button></div></section>
<dialog ref="typeDialog" class="user-type-dialog" aria-labelledby="user-type-title" @cancel.prevent="closeType"><header><h2 id="user-type-title">修改用户类型</h2><button type="button" aria-label="关闭用户类型选择" :disabled="typeEditor?.busy" @click="closeType">×</button></header><UserAccount v-if="typeOpen" ref="typeEditor" :user-id="userId" type-only @cancel="closeType" @changed="typeSaved"/></dialog>
<section class="detail-balance"><span class="stat-icon blue"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M6 9 24 4q2 0 2 2v6H6Z" fill="#008aff" stroke="#d2e9ff"/><rect x="4" y="10" width="24" height="19" rx="3" fill="#006eff" stroke="#87c9ff"/><path d="M6 13h20" stroke="#c4e6ff"/><path d="M24 17h5v8h-5a4 4 0 0 1 0-8Z" fill="#008bff" stroke="#b6ddff"/><circle cx="24" cy="21" r="1.4" fill="white"/></svg></span><div><h3>可用金额（元）</h3><strong :title="detail.user.availableAmount4||undefined">¥ {{yuan(detail.user.availableAmount4)}}</strong></div><button v-if="!adjusting" class="primary-action" @click="openAdjustment"><PromoterIcon name="card"/>调整余额</button></section>
<section v-if="adjusting" class="detail-adjustment"><p v-if="adjustmentBusy" role="status">正在读取账户…</p><p v-else-if="adjustmentError" role="alert">{{adjustmentError}} <button @click="openAdjustment">重试</button></p><AmountAdjustment v-else-if="adjustmentOptions" reference :user-id="userId" :key-id="detail.user.keyId||undefined" :options="adjustmentOptions" :available-amount4="detail.user.availableAmount4" @cancel="cancelAdjustment" @changed="emit('changed')"/><button v-if="!adjustmentOptions" @click="cancelAdjustment">取消</button></section>
<section v-else class="detail-finance reference-detail-finance">
 <article><span class="mini-icon purple"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="m16 2 4 2 4 1 2 4 3 3-1 4 1 5-4 3-2 4-5-1-4 2-4-3-4-1-1-5-2-4 2-4V8l5-2Z" fill="#8b18ff" stroke="#bd8bff"/><path d="m17 8-7 10h5l-1 6 8-11h-5Z" fill="white"/></svg></span><div><h3>可用积分</h3><strong :title="detail.user.availablePoints4||undefined">{{groupedPoints(detail.user.availablePoints4)}}</strong><small :title="detail.user.availableAmount4||undefined">{{detail.user.availableAmount4==null?'≈ —':`≈ ¥ ${yuan(detail.user.availableAmount4)}`}}</small></div></article>
 <article><span class="mini-icon blue"><svg viewBox="0 0 32 32" aria-hidden="true"><rect x="5" y="3" width="23" height="27" rx="3" fill="#007bff" stroke="#8fceff"/><path d="M10 8h12" stroke="white" stroke-width="2" stroke-linecap="round"/><path d="M10 23v-6m5 6v-8m5 8V13" stroke="white" stroke-width="3"/><path d="M9 26h15" stroke="#b6e2ff"/></svg></span><div><h3>累计充值</h3><strong :title="detail.summary?.totalRechargeAmount4||undefined">¥ {{yuan(detail.summary?.totalRechargeAmount4)}}</strong></div></article>
 <article><span class="mini-icon green"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M9 5h4V2h6v3h4v8l4 5v11H5V18l4-5Z" fill="#00bc88" stroke="#8eead0"/><path d="M14 7h4m-4 4h4" stroke="white" stroke-width="2"/><path d="m12 18 4 4 4-4m-4 4v5m-4-4h8" fill="none" stroke="white" stroke-width="2" stroke-linejoin="round"/></svg></span><div><h3>累计消费</h3><strong :title="detail.summary?.netConsumptionAmount4||undefined">{{detail.summary?.netConsumptionAmount4==null?'—':`¥ ${yuan(detail.summary.netConsumptionAmount4)}`}}</strong><small>1 元 = {{formatAmount(pointsPerYuan)}} 积分</small></div></article>
</section>
<section class="detail-records"><div class="record-tabs" role="tablist" aria-label="用户记录"><button v-for="[id,label] in tabs" :id="`user-record-tab-${id}`" :key="id" role="tab" :aria-selected="tab===id" :tabindex="tab===id?0:-1" aria-controls="user-record-panel" @keydown="tabKey" @click="selectTab(id!)">{{label}}</button></div><div id="user-record-panel" role="tabpanel" :aria-labelledby="`user-record-tab-${tab}`" class="record-panel" :aria-busy="recordBusy"><p v-if="recordError" role="alert">{{recordError}} <button @click="loadRecords">重试</button></p><p v-else-if="recordBusy" role="status">正在读取记录…</p>
<template v-else><template v-if="tab==='funds'"><p class="record-scope">最近 100 条 · 积分变动</p><table v-if="ledger.length"><thead><tr><th>时间</th><th>类型</th><th>变动积分</th><th>剩余积分</th></tr></thead><tbody><tr v-for="(row,index) in ledger" :key="index"><td>{{date(row.recordedAt)}}</td><td><span class="pill" :class="row.points4?.startsWith('-')?'red':'green'">{{names[row.kind||'']||row.kind}}</span></td><td :class="row.points4?.startsWith('-')?'negative':'positive'">{{formatAmount(row.points4)}}</td><td>{{formatAmount(row.balanceAfter4)}}</td></tr></tbody></table><p v-else class="directory-empty">暂无资金记录</p></template>
<template v-else-if="tab==='recharges'"><p class="record-scope">最近 100 条</p><table v-if="recharges.length"><thead><tr><th>时间</th><th>金额（元）</th><th>状态</th><th>备注</th></tr></thead><tbody><tr v-for="row in recharges" :key="row.orderId||undefined"><td :title="row.orderId||undefined">{{date(row.createdAt)}}</td><td>{{formatAmount(row.amount4)}}</td><td><span class="pill" :class="row.fulfilled?'green':'neutral'">{{row.fulfilled?'已到账':names[row.status||'']||row.status}}</span></td><td>{{row.remark||'—'}}</td></tr></tbody></table><p v-else class="directory-empty">暂无充值记录</p></template>
<template v-else-if="tab==='audit'"><p class="record-scope">账户扣减审计</p><table v-if="audit.length"><thead><tr><th>时间</th><th>金额（元）</th><th>操作人</th><th>备注</th></tr></thead><tbody><tr v-for="row in audit" :key="row.requestId||undefined"><td>{{date(row.recordedAt)}}</td><td class="negative">−{{formatAmount(row.amount4)}}</td><td>{{row.operatorId||'—'}}</td><td>{{row.remark||'—'}}</td></tr></tbody></table><p v-else class="directory-empty">暂无账户扣减记录</p></template>
<template v-else><p v-if="tab==='generations'" class="record-scope">已计费生成任务</p><table v-if="consumptions.length"><thead><tr><th>时间</th><th>模型</th><th>{{tab==='generations'?'任务状态':'净消耗积分'}}</th><th>操作</th></tr></thead><tbody><tr v-for="row in consumptions" :key="row.ledger?.id||undefined"><td>{{date(row.ledger?.createdAt)}}</td><td>{{row.modelName||row.ledger?.model||'—'}}</td><td>{{tab==='generations'?(names[row.taskStatus||'']||row.taskStatus):formatAmount(row.ledger?.netPoints4)}}</td><td><RouterLink v-if="row.ledger?.id" :to="`/admin/consumption/${encodeURIComponent(row.ledger.id)}`">查看详情</RouterLink></td></tr></tbody></table><p v-else class="directory-empty">暂无{{tab==='generations'?'已计费生成':'消费'}}记录</p><footer v-if="recordTotal>10" class="record-pagination"><span>共 {{recordTotal}} 条</span><button :disabled="recordOffset===0" @click="recordOffset-=10;loadRecords()">上一页</button><button :disabled="recordOffset+10>=recordTotal" @click="recordOffset+=10;loadRecords()">下一页</button></footer></template></template>
</div></section></template></div></template>
